TOOLS.push(...EXTRA_TOOL_DEFS);

function extraShell(panel, title, body) {
  panel.innerHTML = `<div class="form-group"><h2>${escapeHtml(title)}</h2></div>${body}`;
}
function extraTextTool(panel, id) {
  const labels = {
    'character-counter':'Enter text to count characters:', 'sentence-counter':'Enter text to count sentences:',
    'paragraph-counter':'Enter text to count paragraphs:', 'reading-time':'Paste text to estimate reading time:',
    'uppercase-converter':'Text to convert:', 'lowercase-converter':'Text to convert:', 'title-case-converter':'Title to convert:',
    'remove-empty-lines':'Text to clean:', 'text-cleaner':'Text to clean:', 'find-and-replace':'Source text:', 'reverse-text':'Text to reverse:',
    'remove-extra-spaces':'Text to normalize:', 'extract-emails':'Paste text to scan:', 'extract-urls':'Paste text to scan:',
    'extract-numbers':'Paste text to scan:', 'text-to-slug':'Text to turn into a slug:', 'random-text-generator':'Choose output size:'
  };
  let extra = '';
  if (id === 'find-and-replace') extra = '<div class="grid-2"><div class="form-group"><label for="extra-find">Find</label><input id="extra-find" type="text"></div><div class="form-group"><label for="extra-replace">Replace with</label><input id="extra-replace" type="text"></div></div><label class="checkbox-group"><input id="extra-case" type="checkbox"> Match case</label>';
  if (id === 'reverse-text') extra = '<div class="form-group"><label for="extra-mode">Reverse</label><select id="extra-mode"><option value="chars">Characters</option><option value="words">Words in each line</option><option value="lines">Line order</option></select></div>';
  if (id === 'random-text-generator') extra = '<div class="form-group"><label for="extra-size">Number of words</label><input id="extra-size" type="number" min="1" max="2000" value="100"></div>';
  extraShell(panel, TOOLS.find(t => t.id === id).name, `<div class="form-group"><label for="extra-input">${labels[id]}</label><textarea id="extra-input" placeholder="Type or paste here..."></textarea></div>${extra}<div class="btn-group"><button class="btn btn-primary" id="extra-run">${id.includes('counter') || id === 'reading-time' ? 'Analyze' : id === 'random-text-generator' ? 'Generate' : 'Convert'}</button><button class="btn btn-secondary" id="extra-clear">Clear</button></div><section class="output-area" id="extra-out"><h3>Result</h3><pre class="output-content" id="extra-result"></pre><button class="btn btn-secondary" id="extra-copy">Copy</button></section>`);
  const input = panel.querySelector('#extra-input'), result = panel.querySelector('#extra-result'), out = panel.querySelector('#extra-out');
  panel.querySelector('#extra-run').onclick = () => {
    const text = input.value;
    let value;
    if (!text.trim() && !['random-text-generator'].includes(id)) { toast('Enter some text first.', 'error'); return; }
    switch (id) {
      case 'character-counter': value = `Characters (with spaces): ${text.length}\nCharacters (without spaces): ${[...text].filter(c => !/\s/u.test(c)).length}`; break;
      case 'sentence-counter': value = `Sentences: ${(text.match(/[^.!?]+(?:[.!?]+|$)/g) || []).filter(s => s.trim()).length}`; break;
      case 'paragraph-counter': value = `Paragraphs: ${text.split(/\n\s*\n/).filter(s => s.trim()).length}`; break;
      case 'reading-time': { const words = (text.trim().match(/\S+/g) || []).length; value = `${words} words\nEstimated reading time: ${Math.max(1, Math.ceil(words / 225))} minute(s) at 225 words per minute.`; break; }
      case 'uppercase-converter': value = text.toLocaleUpperCase(); break;
      case 'lowercase-converter': value = text.toLocaleLowerCase(); break;
      case 'title-case-converter': value = text.toLocaleLowerCase().replace(/\b[\p{L}\p{N}][\p{L}\p{N}'’-]*/gu, word => word.charAt(0).toLocaleUpperCase() + word.slice(1)); break;
      case 'remove-empty-lines': value = text.split(/\r?\n/).filter(line => line.trim()).join('\n'); break;
      case 'text-cleaner': value = text.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').replace(/\r\n?/g, '\n').replace(/[\t ]+/g, ' ').trim(); break;
      case 'find-and-replace': { const find = panel.querySelector('#extra-find').value; if (!find) { toast('Enter text to find.', 'error'); return; } const escaped = find.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); value = text.replace(new RegExp(escaped, panel.querySelector('#extra-case').checked ? 'g' : 'gi'), panel.querySelector('#extra-replace').value); break; }
      case 'reverse-text': { const mode = panel.querySelector('#extra-mode').value; value = mode === 'chars' ? [...text].reverse().join('') : mode === 'words' ? text.split(/\r?\n/).map(line => line.split(/\s+/).reverse().join(' ')).join('\n') : text.split(/\r?\n/).reverse().join('\n'); break; }
      case 'remove-extra-spaces': value = text.split(/\r?\n/).map(line => line.trim().replace(/[\t ]+/g, ' ')).join('\n'); break;
      case 'extract-emails': value = [...new Set(text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [])].join('\n') || 'No email addresses found.'; break;
      case 'extract-urls': value = [...new Set(text.match(/https?:\/\/[^\s<>"']+/gi) || [])].join('\n') || 'No HTTP(S) URLs found.'; break;
      case 'extract-numbers': value = (text.match(/[-+]?(?:\d+\.?\d*|\.\d+)(?:e[-+]?\d+)?/gi) || []).join('\n') || 'No numbers found.'; break;
      case 'text-to-slug': value = text.normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, ''); break;
      case 'random-text-generator': { const words = 'clear useful words make concise sentences readable content for testing layouts and samples in a browser without external services'.split(' '); const count = Math.min(2000, Math.max(1, Number(panel.querySelector('#extra-size').value) || 1)); value = Array.from({length:count}, (_, i) => words[crypto.getRandomValues(new Uint32Array(1))[0] % words.length] + (i % 16 === 15 ? '.' : '')).join(' '); break; }
    }
    result.textContent = value; out.classList.add('visible');
  };
  panel.querySelector('#extra-clear').onclick = () => { input.value = ''; out.classList.remove('visible'); };
  panel.querySelector('#extra-copy').onclick = () => copyText(result.textContent);
}

function extraDeveloperTool(panel, id) {
  const name = TOOLS.find(t => t.id === id).name;
  let extras = '';
  if (id === 'regex-tester') extras = '<div class="grid-2"><div class="form-group"><label for="extra-pattern">Regular expression</label><input id="extra-pattern" type="text" placeholder="\\btool\\w*"></div><div class="form-group"><label for="extra-flags">Flags</label><input id="extra-flags" type="text" value="gi" maxlength="6"></div></div>';
  extraShell(panel, name, `<div class="form-group"><label for="extra-input">Input</label><textarea id="extra-input" placeholder="Paste or type your data..."></textarea></div>${extras}<div class="btn-group"><button class="btn btn-primary" id="extra-run">${id.includes('validator') ? 'Validate' : id === 'regex-tester' ? 'Test expression' : 'Convert'}</button><button class="btn btn-secondary" id="extra-clear">Clear</button></div><section class="output-area" id="extra-out"><h3 id="extra-status">Result</h3><pre class="output-content" id="extra-result"></pre><button class="btn btn-secondary" id="extra-copy">Copy</button></section>`);
  const input = panel.querySelector('#extra-input'), result = panel.querySelector('#extra-result'), out = panel.querySelector('#extra-out'), status = panel.querySelector('#extra-status');
  panel.querySelector('#extra-run').onclick = () => {
    const text = input.value;
    try {
      let value;
      switch (id) {
        case 'json-minifier': value = JSON.stringify(JSON.parse(text)); break;
        case 'json-to-csv': { const rows = JSON.parse(text); if (!Array.isArray(rows) || !rows.every(row => row && typeof row === 'object' && !Array.isArray(row))) throw Error('Expected a JSON array of objects.'); const keys = [...new Set(rows.flatMap(Object.keys))]; value = [keys, ...rows.map(row => keys.map(key => row[key] ?? ''))].map(row => row.map(cell => { const str = typeof cell === 'object' ? JSON.stringify(cell) : String(cell); return `"${str.replace(/"/g, '""')}"`; }).join(',')).join('\n'); break; }
        case 'csv-to-json': { const rows = parseCsv(text); if (rows.length < 2) throw Error('Include a header row and at least one data row.'); const headers = rows[0]; value = JSON.stringify(rows.slice(1).filter(r => r.some(v => v !== '')).map(row => Object.fromEntries(headers.map((h, i) => [h, row[i] ?? '']))), null, 2); break; }
        case 'html-encoder': value = text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#39;'); break;
        case 'html-decoder': { const area = document.createElement('textarea'); area.innerHTML = text; value = area.value; break; }
        case 'jwt-decoder': { const pieces = text.trim().split('.'); if (pieces.length !== 3) throw Error('A JWT must contain three dot-separated parts.'); const decode = part => JSON.stringify(JSON.parse(decodeURIComponent(Array.from(atob(part.replace(/-/g,'+').replace(/_/g,'/')), c => '%' + c.charCodeAt(0).toString(16).padStart(2,'0')).join(''))), null, 2); value = `Header (unverified):\n${decode(pieces[0])}\n\nPayload (unverified):\n${decode(pieces[1])}\n\nSignature verification is not performed.`; break; }
        case 'timestamp-converter': { const n = Number(text.trim()); if (!Number.isFinite(n)) throw Error('Enter a Unix timestamp in seconds or milliseconds.'); const date = new Date(Math.abs(n) < 1e12 ? n * 1000 : n); if (Number.isNaN(date.getTime())) throw Error('Timestamp is outside the supported date range.'); value = `UTC: ${date.toISOString()}\nLocal: ${date.toString()}\nMilliseconds: ${date.getTime()}`; break; }
        case 'regex-tester': { const regex = new RegExp(panel.querySelector('#extra-pattern').value, panel.querySelector('#extra-flags').value); const matches = [...text.matchAll(regex)].slice(0, 500); value = matches.length ? matches.map(m => `${m[0]} (index ${m.index})`).join('\n') : 'No matches.'; break; }
        case 'css-minifier': value = text.replace(/\/\*[\s\S]*?\*\//g, '').replace(/\s+/g, ' ').replace(/\s*([{}:;,>])\s*/g, '$1').trim(); break;
        case 'xml-validator': { const doc = new DOMParser().parseFromString(text, 'application/xml'); const error = doc.querySelector('parsererror'); if (error) throw Error(error.textContent.trim()); value = 'Valid XML document.'; break; }
      }
      status.textContent = 'Success'; result.textContent = value; out.classList.add('visible');
    } catch (error) { status.textContent = 'Input error'; result.textContent = error.message; out.classList.add('visible'); }
  };
  panel.querySelector('#extra-clear').onclick = () => { input.value = ''; out.classList.remove('visible'); };
  panel.querySelector('#extra-copy').onclick = () => copyText(result.textContent);
}
function parseCsv(text) {
  const rows = []; let row = [], cell = '', quoted = false;
  for (let i = 0; i < text.length; i++) { const c = text[i]; if (quoted && c === '"' && text[i + 1] === '"') { cell += '"'; i++; } else if (c === '"') quoted = !quoted; else if (c === ',' && !quoted) { row.push(cell); cell = ''; } else if ((c === '\n' || c === '\r') && !quoted) { if (c === '\r' && text[i + 1] === '\n') i++; row.push(cell); rows.push(row); row = []; cell = ''; } else cell += c; }
  if (quoted) throw Error('CSV contains an unclosed quoted field.'); if (cell || row.length) { row.push(cell); rows.push(row); } return rows;
}

function ipToInt(value) { const parts = value.trim().split('.'); if (parts.length !== 4 || parts.some(part => !/^\d{1,3}$/.test(part) || Number(part) > 255)) throw Error('Enter a valid IPv4 address.'); return parts.reduce((n, part) => n * 256 + Number(part), 0); }
function intToIp(value) { return [24,16,8,0].map(shift => Math.floor(value / (2 ** shift)) % 256).join('.'); }
function extraNetworkingTool(panel, id) {
  const name = TOOLS.find(t => t.id === id).name;
  let body = '';
  if (['ipv4-subnet-calculator','cidr-calculator'].includes(id)) body = '<div class="form-group"><label for="extra-cidr">IPv4 address / prefix</label><input id="extra-cidr" type="text" value="192.168.1.10/24" placeholder="192.168.1.10/24"></div>';
  else if (id === 'ip-range-calculator') body = '<div class="grid-2"><div class="form-group"><label for="extra-a">Start IPv4</label><input id="extra-a" value="192.168.1.1"></div><div class="form-group"><label for="extra-b">End IPv4</label><input id="extra-b" value="192.168.1.20"></div></div>';
  else if (id === 'binary-to-ipv4') body = '<div class="form-group"><label for="extra-input">Four 8-bit octets (spaces or dots)</label><input id="extra-input" value="11000000.10101000.00000001.00000001"></div>';
  else if (id === 'mac-address-formatter') body = '<div class="form-group"><label for="extra-input">MAC address</label><input id="extra-input" placeholder="00:1A:2B:3C:4D:5E"></div>';
  else if (id === 'http-status-reference') body = '<div class="form-group"><label for="extra-input">Search code or phrase</label><input id="extra-input" placeholder="404"></div>';
  else body = `<div class="form-group"><label for="extra-input">${id.includes('ipv4') ? 'IPv4 address' : 'Integer'}</label><input id="extra-input" placeholder="192.168.1.1" value="${id === 'user-agent-viewer' ? '' : id.includes('ipv4') ? '192.168.1.1' : '42'}"></div>`;
  extraShell(panel, name, `${body}<div class="btn-group"><button class="btn btn-primary" id="extra-run">${id === 'http-status-reference' ? 'Search' : 'Calculate'}</button></div><section class="output-area" id="extra-out"><h3>Result</h3><pre class="output-content" id="extra-result"></pre></section>`);
  const result = panel.querySelector('#extra-result'), out = panel.querySelector('#extra-out');
  panel.querySelector('#extra-run').onclick = () => { try {
    let value;
    if (id === 'user-agent-viewer') value = navigator.userAgent;
    else if (id === 'ipv4-to-binary') value = ipToInt(panel.querySelector('#extra-input').value) >= 0 ? panel.querySelector('#extra-input').value.trim().split('.').map(o => Number(o).toString(2).padStart(8,'0')).join('.') : '';
    else if (id === 'binary-to-ipv4') { const bits = panel.querySelector('#extra-input').value.trim().split(/[.\s]+/); if (bits.length !== 4 || bits.some(x => !/^[01]{8}$/.test(x))) throw Error('Enter exactly four 8-bit binary octets.'); value = bits.map(x => parseInt(x,2)).join('.'); }
    else if (id === 'decimal-to-binary' || id === 'binary-to-decimal') { const raw = panel.querySelector('#extra-input').value.trim(); const n = id === 'decimal-to-binary' ? Number(raw) : /^[01]+$/.test(raw) ? parseInt(raw,2) : NaN; if (!Number.isSafeInteger(n) || n < 0) throw Error('Enter a non-negative safe integer in the selected format.'); value = id === 'decimal-to-binary' ? n.toString(2) : String(n); }
    else if (id === 'mac-address-formatter') { const hex = panel.querySelector('#extra-input').value.replace(/[^a-f\d]/gi,''); if (!/^[a-f\d]{12}$/i.test(hex)) throw Error('Enter a 48-bit MAC address (12 hexadecimal digits).'); const pairs = hex.match(/.{2}/g); value = `Colon: ${pairs.join(':').toUpperCase()}\nHyphen: ${pairs.join('-').toUpperCase()}\nCisco: ${hex.match(/.{4}/g).join('.').toUpperCase()}`; }
    else if (id === 'http-status-reference') { const statuses = [[100,'Continue'],[101,'Switching Protocols'],[200,'OK'],[201,'Created'],[202,'Accepted'],[204,'No Content'],[206,'Partial Content'],[301,'Moved Permanently'],[302,'Found'],[304,'Not Modified'],[307,'Temporary Redirect'],[308,'Permanent Redirect'],[400,'Bad Request'],[401,'Unauthorized'],[403,'Forbidden'],[404,'Not Found'],[405,'Method Not Allowed'],[409,'Conflict'],[410,'Gone'],[413,'Content Too Large'],[415,'Unsupported Media Type'],[418,"I'm a teapot"],[422,'Unprocessable Content'],[429,'Too Many Requests'],[500,'Internal Server Error'],[501,'Not Implemented'],[502,'Bad Gateway'],[503,'Service Unavailable'],[504,'Gateway Timeout']]; const q = panel.querySelector('#extra-input').value.trim().toLowerCase(); value = statuses.filter(([code,label]) => !q || String(code).includes(q) || label.toLowerCase().includes(q)).map(([code,label]) => `${code} ${label}`).join('\n') || 'No matching status codes.'; }
    else if (id === 'ip-range-calculator') { const a = ipToInt(panel.querySelector('#extra-a').value), b = ipToInt(panel.querySelector('#extra-b').value); if (a > b) throw Error('Start address must not be after end address.'); value = `First: ${intToIp(a)}\nLast: ${intToIp(b)}\nAddress count: ${b - a + 1}`; }
    else { const [addr, prefixRaw] = panel.querySelector('#extra-cidr').value.trim().split('/'); const ip = ipToInt(addr); const prefix = prefixRaw === undefined ? 32 : Number(prefixRaw); if (!Number.isInteger(prefix) || prefix < 0 || prefix > 32) throw Error('Prefix must be between 0 and 32.'); const block = 2 ** (32 - prefix); const network = Math.floor(ip / block) * block, broadcast = network + block - 1; value = `Network: ${intToIp(network)}\nFirst address: ${prefix >= 31 ? intToIp(network) : intToIp(network + 1)}\nLast address: ${prefix >= 31 ? intToIp(broadcast) : intToIp(broadcast - 1)}\nBroadcast: ${intToIp(broadcast)}\nPrefix: /${prefix}\nSubnet mask: ${intToIp(0xFFFFFFFF - (block - 1))}\nTotal addresses: ${block}\nUsable hosts: ${prefix >= 31 ? block : Math.max(0, block - 2)}`; }
    result.textContent = value; out.classList.add('visible');
  } catch (error) { result.textContent = error.message; out.classList.add('visible'); } };
}

function extraCalculator(panel, id) {
  const name = TOOLS.find(t => t.id === id).name;
  let fields = '';
  const definitions = {
    'discount-calculator':[['price','Original price',100],['rate','Discount (%)',10]], 'tip-calculator':[['price','Bill total',50],['rate','Tip (%)',18],['people','People',2]],
    'bmi-calculator':[['weight','Weight (kg)',70],['height','Height (cm)',175]], 'loan-calculator':[['principal','Loan amount',20000],['rate','Annual interest (%)',6],['years','Term (years)',5]],
    'simple-interest-calculator':[['principal','Principal',1000],['rate','Annual rate (%)',5],['years','Years',3]], 'compound-interest-calculator':[['principal','Principal',1000],['rate','Annual rate (%)',5],['years','Years',10],['frequency','Compounds per year',12]],
    'tax-calculator':[['price','Price before tax',100],['rate','Tax rate (%)',10]], 'salary-calculator':[['salary','Annual gross salary',60000],['hours','Hours per week',40]],
    'grade-calculator':[['earned','Points earned',85],['possible','Points possible',100]], 'exam-marks-calculator':[['earned','Marks earned',72],['possible','Total marks',100],['target','Target percentage',80]]
  }[id] || [];
  if (id === 'age-calculator') fields = '<div class="form-group"><label for="extra-date">Date of birth</label><input id="extra-date" type="date"></div>';
  else fields = `<div class="grid-2">${definitions.map(([key,label,val]) => `<div class="form-group"><label for="extra-${key}">${label}</label><input id="extra-${key}" type="number" step="any" value="${val}"></div>`).join('')}</div>`;
  extraShell(panel, name, `${fields}<div class="btn-group"><button class="btn btn-primary" id="extra-run">Calculate</button></div><section class="output-area" id="extra-out"><h3>Result</h3><pre class="output-content" id="extra-result"></pre></section>`);
  const result = panel.querySelector('#extra-result'), out = panel.querySelector('#extra-out');
  panel.querySelector('#extra-run').onclick = () => { try {
    let value;
    if (id === 'age-calculator') { const birth = new Date(panel.querySelector('#extra-date').value + 'T00:00:00'); if (!panel.querySelector('#extra-date').value || birth > new Date()) throw Error('Choose a valid date of birth in the past.'); const now = new Date(); let years = now.getFullYear() - birth.getFullYear(), months = now.getMonth() - birth.getMonth(), days = now.getDate() - birth.getDate(); if (days < 0) { months--; days += new Date(now.getFullYear(), now.getMonth(), 0).getDate(); } if (months < 0) { years--; months += 12; } value = `${years} years, ${months} months, ${days} days`; }
    else { const n = key => Number(panel.querySelector(`#extra-${key}`).value); const finite = keys => keys.every(k => Number.isFinite(n(k))); let r;
      if (id === 'discount-calculator') { if (!finite(['price','rate']) || n('price') < 0 || n('rate') < 0 || n('rate') > 100) throw Error('Enter a non-negative price and a discount from 0 to 100%.'); r = n('price') * (1 - n('rate') / 100); value = `Sale price: ${r.toFixed(2)}\nYou save: ${(n('price')-r).toFixed(2)}`; }
      if (id === 'tip-calculator') { if (!finite(['price','rate','people']) || n('price') < 0 || n('people') < 1) throw Error('Enter a valid bill, tip rate, and at least one person.'); const tip=n('price')*n('rate')/100; value=`Tip: ${tip.toFixed(2)}\nTotal: ${(n('price')+tip).toFixed(2)}\nPer person: ${((n('price')+tip)/Math.floor(n('people'))).toFixed(2)}`; }
      if (id === 'bmi-calculator') { if (!finite(['weight','height']) || n('weight') <= 0 || n('height') <= 0) throw Error('Weight and height must be positive.'); r=n('weight')/((n('height')/100)**2); value=`BMI: ${r.toFixed(1)}\nAdult reference category: ${r<18.5?'below 18.5':r<25?'18.5-24.9':r<30?'25-29.9':'30 or above'}\nBMI is a screening measure, not a diagnosis.`; }
      if (id === 'loan-calculator') { if (!finite(['principal','rate','years']) || n('principal') <= 0 || n('rate') < 0 || n('years') <= 0) throw Error('Enter a positive principal and term, and a non-negative rate.'); const m=n('rate')/1200, count=n('years')*12; r=m===0?n('principal')/count:n('principal')*m/(1-Math.pow(1+m,-count)); value=`Estimated monthly payment: ${r.toFixed(2)}\nTotal paid: ${(r*count).toFixed(2)}\nTotal interest: ${(r*count-n('principal')).toFixed(2)}\nEstimate excludes fees and taxes.`; }
      if (id === 'simple-interest-calculator') { if (!finite(['principal','rate','years']) || n('principal') < 0 || n('rate') < 0 || n('years') < 0) throw Error('Values must be non-negative.'); r=n('principal')*n('rate')/100*n('years'); value=`Interest: ${r.toFixed(2)}\nFinal balance: ${(n('principal')+r).toFixed(2)}`; }
      if (id === 'compound-interest-calculator') { if (!finite(['principal','rate','years','frequency']) || n('principal') < 0 || n('rate') < 0 || n('years') < 0 || n('frequency') < 1) throw Error('Enter non-negative values and a compounding frequency of at least one.'); r=n('principal')*Math.pow(1+n('rate')/(100*n('frequency')),n('frequency')*n('years')); value=`Final balance: ${r.toFixed(2)}\nGrowth: ${(r-n('principal')).toFixed(2)}\nAssumes no additional contributions.`; }
      if (id === 'tax-calculator') { if (!finite(['price','rate']) || n('price') < 0 || n('rate') < 0) throw Error('Enter non-negative price and tax rate.'); r=n('price')*n('rate')/100; value=`Tax: ${r.toFixed(2)}\nTotal including tax: ${(n('price')+r).toFixed(2)}`; }
      if (id === 'salary-calculator') { if (!finite(['salary','hours']) || n('salary') < 0 || n('hours') <= 0) throw Error('Salary must be non-negative and weekly hours must be positive.'); value=`Annual: ${n('salary').toFixed(2)}\nMonthly: ${(n('salary')/12).toFixed(2)}\nWeekly: ${(n('salary')/52).toFixed(2)}\nHourly estimate (52 weeks): ${(n('salary')/(52*n('hours'))).toFixed(2)}\nGross estimate before deductions.`; }
      if (id === 'grade-calculator' || id === 'exam-marks-calculator') { if (!finite(id === 'grade-calculator'?['earned','possible']:['earned','possible','target']) || n('possible') <= 0 || n('earned') < 0) throw Error('Enter non-negative earned marks and a positive total.'); r=n('earned')/n('possible')*100; value=`Current percentage: ${r.toFixed(2)}%${id==='exam-marks-calculator'?`\nTarget marks: ${(n('possible')*n('target')/100).toFixed(2)}\nAdditional marks needed: ${Math.max(0,n('possible')*n('target')/100-n('earned')).toFixed(2)}`:''}`; }
    }
    result.textContent = value; out.classList.add('visible');
  } catch (error) { result.textContent = error.message; out.classList.add('visible'); } };
}

function extraDateTool(panel, id) {
  const name=TOOLS.find(t=>t.id===id).name; let body='';
  if (id==='date-difference-calculator') body='<div class="grid-2"><div class="form-group"><label for="extra-a">Start date</label><input id="extra-a" type="date"></div><div class="form-group"><label for="extra-b">End date</label><input id="extra-b" type="date"></div></div>';
  if (id==='add-subtract-days') body='<div class="grid-2"><div class="form-group"><label for="extra-date">Date</label><input id="extra-date" type="date"></div><div class="form-group"><label for="extra-days">Days (negative subtracts)</label><input id="extra-days" type="number" value="30"></div></div>';
  if (id==='unix-time-converter') body='<div class="form-group"><label for="extra-input">Unix timestamp (seconds or milliseconds)</label><input id="extra-input" type="number" step="any"></div>';
  if (id==='calendar-generator') body='<div class="grid-2"><div class="form-group"><label for="extra-month">Month</label><input id="extra-month" type="month"></div><div class="form-group"><label for="extra-start">Week starts</label><select id="extra-start"><option value="0">Sunday</option><option value="1">Monday</option></select></div></div>';
  if (id==='world-clock') body='<div class="form-group"><label for="extra-zones">Time zones (one IANA name per line)</label><textarea id="extra-zones">UTC\nAmerica/New_York\nEurope/London\nAsia/Tokyo</textarea></div>';
  if (id==='countdown-timer'||id==='pomodoro-timer'||id==='study-timer') body=`<div class="grid-2"><div class="form-group"><label for="extra-minutes">${id==='pomodoro-timer'?'Work minutes':'Minutes'}</label><input id="extra-minutes" type="number" value="${id==='pomodoro-timer'?25:5}" min="1" max="240"></div>${id==='pomodoro-timer'?'<div class="form-group"><label for="extra-break">Break minutes</label><input id="extra-break" type="number" value="5" min="1" max="120"></div>':''}</div><div id="timer-display" role="timer" style="font-size:2rem;font-variant-numeric:tabular-nums;margin:1rem 0;"></div><div class="btn-group"><button class="btn btn-primary" id="timer-start">Start</button><button class="btn btn-secondary" id="timer-reset">Reset</button></div>`;
  extraShell(panel,name,`${body}${!['countdown-timer','pomodoro-timer','study-timer'].includes(id)?'<div class="btn-group"><button class="btn btn-primary" id="extra-run">Calculate</button></div>':''}<section class="output-area" id="extra-out"><h3>Result</h3><div id="extra-result"></div></section>`);
  const out=panel.querySelector('#extra-out'), result=panel.querySelector('#extra-result');
  if (['countdown-timer','pomodoro-timer','study-timer'].includes(id)) { const display=panel.querySelector('#timer-display'), start=panel.querySelector('#timer-start'); let initial=Math.max(1,Number(panel.querySelector('#extra-minutes').value)||1)*60, remain=initial, timer=null, phase='work'; const show=()=>display.textContent=`${String(Math.floor(remain/60)).padStart(2,'0')}:${String(remain%60).padStart(2,'0')}`; panel.querySelector('#extra-minutes').oninput=()=>{ if(!timer){initial=Math.max(1,Number(panel.querySelector('#extra-minutes').value)||1)*60;remain=initial;show();}}; show(); start.onclick=()=>{if(timer){clearInterval(timer);timer=null;start.textContent='Resume';return;} start.textContent='Pause'; timer=setInterval(()=>{remain--;show();if(remain<=0){clearInterval(timer);timer=null;if(id==='pomodoro-timer'&&phase==='work'){phase='break';remain=Math.max(1,Number(panel.querySelector('#extra-break').value)||5)*60;display.setAttribute('aria-label','Break time');start.textContent='Start break';}else{start.textContent='Start';toast('Timer finished.','success');}show();}},1000);};panel.querySelector('#timer-reset').onclick=()=>{clearInterval(timer);timer=null;phase='work';remain=initial;start.textContent='Start';show();}; return; }
  panel.querySelector('#extra-run').onclick=()=>{try{let value;if(id==='date-difference-calculator'){const a=new Date(panel.querySelector('#extra-a').value+'T00:00:00Z'),b=new Date(panel.querySelector('#extra-b').value+'T00:00:00Z');if(Number.isNaN(+a)||Number.isNaN(+b))throw Error('Choose both dates.');value=`Elapsed days: ${Math.abs(Math.round((b-a)/86400000))}`;}if(id==='add-subtract-days'){const date=new Date(panel.querySelector('#extra-date').value+'T12:00:00');const days=Number(panel.querySelector('#extra-days').value);if(Number.isNaN(+date)||!Number.isInteger(days))throw Error('Choose a valid date and whole number of days.');date.setDate(date.getDate()+days);value=date.toLocaleDateString(undefined,{dateStyle:'full'});}if(id==='unix-time-converter'){const n=Number(panel.querySelector('#extra-input').value);if(!Number.isFinite(n))throw Error('Enter a timestamp.');const d=new Date(Math.abs(n)<1e12?n*1000:n);if(Number.isNaN(+d))throw Error('Timestamp is out of range.');value=`Local: ${d.toString()}\nUTC: ${d.toISOString()}\nSeconds: ${Math.floor(+d/1000)}\nMilliseconds: ${+d}`;}if(id==='world-clock'){const zones=panel.querySelector('#extra-zones').value.split(/\r?\n/).map(z=>z.trim()).filter(Boolean);value=zones.map(zone=>`${zone}: ${new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'medium',timeZone:zone}).format(new Date())}`).join('\n');}if(id==='calendar-generator'){const raw=panel.querySelector('#extra-month').value;if(!raw)throw Error('Choose a month.');const [y,m]=raw.split('-').map(Number),first=new Date(y,m-1,1),offset=(first.getDay()-Number(panel.querySelector('#extra-start').value)+7)%7,days=new Date(y,m,0).getDate();let rows=['Su Mo Tu We Th Fr Sa'];if(panel.querySelector('#extra-start').value==='1')rows=['Mo Tu We Th Fr Sa Su'];let row=Array(7).fill('  ');for(let d=1;d<=days;d++){const index=(offset+d-1)%7;row[index]=String(d).padStart(2,' ');if(index===6){rows.push(row.join(' '));row=Array(7).fill('  ');}}if(row.some(x=>x.trim()))rows.push(row.join(' '));value=`${new Intl.DateTimeFormat(undefined,{month:'long',year:'numeric'}).format(first)}\n${rows.join('\n')}`;}result.textContent=value;out.classList.add('visible');}catch(error){result.textContent=error.message;out.classList.add('visible');}};
}

function extraStudentTool(panel,id){const name=TOOLS.find(t=>t.id===id).name;let body='';if(id==='random-choice-picker')body='<div class="form-group"><label for="extra-input">Choices (one per line)</label><textarea id="extra-input" placeholder="Option A\nOption B"></textarea></div>';else if(id==='percentage-to-gpa')body='<div class="form-group"><label for="extra-percentage">Percentage (0-100)</label><input id="extra-percentage" type="number" min="0" max="100" value="85"></div>';else body=`<div class="form-group"><label for="extra-rows">${id==='exam-marks-calculator'?'': 'Grade and credits, one course per line (example: A,3)'}</label><textarea id="extra-rows" placeholder="A,3\nB+,4\nA-,3"></textarea></div><p>Scale: A=4.0, A-=3.7, B+=3.3, B=3.0, B-=2.7, C+=2.3, C=2.0, C-=1.7, D=1.0, F=0.</p>`;extraShell(panel,name,`${body}<div class="btn-group"><button class="btn btn-primary" id="extra-run">Calculate / Pick</button></div><section class="output-area" id="extra-out"><h3>Result</h3><pre class="output-content" id="extra-result"></pre></section>`);const result=panel.querySelector('#extra-result'),out=panel.querySelector('#extra-out');panel.querySelector('#extra-run').onclick=()=>{try{let value;if(id==='random-choice-picker'){const options=panel.querySelector('#extra-input').value.split(/\r?\n/).map(x=>x.trim()).filter(Boolean);if(!options.length)throw Error('Enter at least one choice.');value=options[crypto.getRandomValues(new Uint32Array(1))[0]%options.length];}else if(id==='percentage-to-gpa'){const n=Number(panel.querySelector('#extra-percentage').value);if(n<0||n>100)throw Error('Percentage must be between 0 and 100.');value=`Estimated GPA: ${(n/25).toFixed(2)} / 4.00\nThis is a simple linear estimate; grading scales vary by institution.`;}else{const rows=panel.querySelector('#extra-rows').value.split(/\r?\n/).filter(x=>x.trim()).map(line=>line.split(/[,:\t]/).map(x=>x.trim()));if(!rows.length)throw Error('Add at least one grade and credit value.');const scale={'A':4,'A-':3.7,'B+':3.3,'B':3,'B-':2.7,'C+':2.3,'C':2,'C-':1.7,'D':1,'F':0};let points=0,credits=0;for(const [grade,creditText] of rows){const c=Number(creditText);const g=scale[grade.toUpperCase()];if(g===undefined||!Number.isFinite(c)||c<=0)throw Error(`Invalid grade or credit value in: ${grade}, ${creditText}`);points+=g*c;credits+=c;}value=`${id==='cgpa-calculator'?'Cumulative GPA':'Weighted GPA'}: ${(points/credits).toFixed(2)} / 4.00\nTotal credits: ${credits}`;}result.textContent=value;out.classList.add('visible');}catch(error){result.textContent=error.message;out.classList.add('visible');}};}

function extraImageTool(panel,id){if(['jpg-to-png','png-to-jpg','webp-to-jpg','jpg-to-webp','png-to-webp','webp-to-png'].includes(id)){renderImageConverter(panel);const map={'jpg-to-png':'image/png','png-to-jpg':'image/jpeg','webp-to-jpg':'image/jpeg','jpg-to-webp':'image/webp','png-to-webp':'image/webp','webp-to-png':'image/png'};panel.querySelector('#icv-format').value=map[id];panel.querySelector('#icv-format').disabled=true;return;}const name=TOOLS.find(t=>t.id===id).name;extraShell(panel,name,`<div class="drop-zone" id="extra-drop" tabindex="0"><span class="drop-zone-icon">▧</span><p><strong>Select an image</strong> or drag it here</p><small>Processed locally in your browser</small><input id="extra-file" type="file" accept="image/*" hidden></div><div id="extra-options"></div><div class="btn-group"><button class="btn btn-primary" id="extra-run" disabled>Process image</button></div><section class="output-area" id="extra-out"><h3>Result</h3><div id="extra-result"></div></section>`);const drop=panel.querySelector('#extra-drop'),fileInput=panel.querySelector('#extra-file'),run=panel.querySelector('#extra-run'),options=panel.querySelector('#extra-options'),out=panel.querySelector('#extra-out'),result=panel.querySelector('#extra-result');let file=null;drop.onclick=()=>fileInput.click();drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();fileInput.click();}};drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');select(e.dataTransfer.files[0]);};fileInput.onchange=e=>select(e.target.files[0]);function select(f){if(!f||!f.type.startsWith('image/')){toast('Choose a supported image file.','error');return;}file=f;drop.querySelector('p').textContent=`${f.name} (${formatBytes(f.size)})`;run.disabled=false;if(id==='image-rotator')options.innerHTML='<label for="extra-angle">Rotation</label><select id="extra-angle"><option value="90">90° clockwise</option><option value="180">180°</option><option value="270">270° clockwise</option></select>';if(id==='image-flipper')options.innerHTML='<label for="extra-flip">Flip direction</label><select id="extra-flip"><option value="horizontal">Horizontal</option><option value="vertical">Vertical</option></select>';if(id==='blur-image')options.innerHTML='<label for="extra-blur">Blur: <span id="extra-blur-value">4</span>px</label><input id="extra-blur" type="range" min="1" max="20" value="4">';if(id==='add-text-to-image'||id==='add-watermark-to-image')options.innerHTML='<div class="form-group"><label for="extra-label">Overlay text</label><input id="extra-label" type="text" maxlength="120" value="ToolNest"></div>';if(id==='image-color-picker')options.innerHTML='<p>Click a point on the image preview to read its pixel color.</p>';loadImage(f).then(({img})=>{const preview=document.createElement('img');preview.src=img.src;preview.alt='Selected image preview';preview.className='img-preview';preview.id='extra-preview';result.replaceChildren(preview);if(id==='image-metadata-viewer'){result.insertAdjacentHTML('beforeend',`<p>Dimensions: ${img.naturalWidth} × ${img.naturalHeight} px</p><p>File type: ${escapeHtml(f.type||'unknown')}</p><p>File size: ${formatBytes(f.size)}</p>`);out.classList.add('visible');}if(id==='image-color-picker')preview.onclick=e=>{const rect=preview.getBoundingClientRect(),x=Math.floor((e.clientX-rect.left)*img.naturalWidth/rect.width),y=Math.floor((e.clientY-rect.top)*img.naturalHeight/rect.height),c=document.createElement('canvas');c.width=c.height=1;const ctx=c.getContext('2d',{willReadFrequently:true});ctx.drawImage(img,x,y,1,1,0,0,1,1);const [r,g,b]=ctx.getImageData(0,0,1,1).data;const hex='#'+[r,g,b].map(v=>v.toString(16).padStart(2,'0')).join('');result.querySelector('#pixel-color')?.remove();result.insertAdjacentHTML('beforeend',`<p id="pixel-color">${hex.toUpperCase()} · rgb(${r}, ${g}, ${b})</p>`);};}).catch(()=>toast('This image could not be opened by the browser.','error'));}run.onclick=async()=>{if(!file)return;try{const {img}=await loadImage(file);const angle=id==='image-rotator'?Number(panel.querySelector('#extra-angle').value):0;const flip=id==='image-flipper'?panel.querySelector('#extra-flip').value:'';const w=angle%180?img.naturalHeight:img.naturalWidth,h=angle%180?img.naturalWidth:img.naturalHeight,c=document.createElement('canvas');c.width=w;c.height=h;const ctx=c.getContext('2d');ctx.translate(w/2,h/2);if(flip==='horizontal')ctx.scale(-1,1);if(flip==='vertical')ctx.scale(1,-1);if(angle)ctx.rotate(angle*Math.PI/180);if(id==='grayscale-image')ctx.filter='grayscale(1)';if(id==='blur-image')ctx.filter=`blur(${panel.querySelector('#extra-blur').value}px)`;ctx.drawImage(img,-img.naturalWidth/2,-img.naturalHeight/2);if(id==='add-text-to-image'||id==='add-watermark-to-image'){ctx.filter='none';ctx.font=`${Math.max(18,Math.round(w/24))}px sans-serif`;ctx.fillStyle='rgba(255,255,255,.85)';ctx.strokeStyle='rgba(0,0,0,.8)';ctx.lineWidth=3;const text=panel.querySelector('#extra-label').value;if(!text)throw Error('Enter overlay text.');ctx.strokeText(text,16,h-24);ctx.fillText(text,16,h-24);}const blob=await new Promise(resolve=>c.toBlob(resolve,'image/png'));if(!blob)throw Error('Could not encode the processed image.');const image=document.createElement('img');image.src=URL.createObjectURL(blob);image.alt='Processed image preview';image.className='img-preview';const button=document.createElement('button');button.className='btn btn-primary';button.textContent='Download PNG';button.onclick=()=>downloadBlob(blob,'toolnest-image.png');result.replaceChildren(image,button);out.classList.add('visible');}catch(error){toast(error.message||'Image processing failed.','error');}};}

async function loadPdfLib(){if(!window.PDFLib)await loadScript('https://unpkg.com/pdf-lib@1.17.1/dist/pdf-lib.min.js');return window.PDFLib;}
function extraPdfTool(panel,id){const name=TOOLS.find(t=>t.id===id).name;const merge=id==='merge-pdf';extraShell(panel,name,`<div class="drop-zone" id="extra-drop" tabindex="0"><span class="drop-zone-icon">▤</span><p><strong>Select ${merge?'PDF files':'a PDF file'}</strong> or drag files here</p><small>PDF processing happens in your browser; files are not uploaded.</small><input id="extra-file" type="file" accept="application/pdf,.pdf" ${merge?'multiple':''} hidden></div><div id="extra-info"></div>${id==='split-pdf'?'<div class="form-group"><label for="extra-pages">Pages to extract (1-based, e.g. 1,3-5)</label><input id="extra-pages" type="text" value="1"></div>':''}<div class="btn-group"><button class="btn btn-primary" id="extra-run" disabled>${merge?'Merge PDFs':id==='split-pdf'?'Extract pages':'Read PDF details'}</button></div><section class="output-area" id="extra-out"><h3>Result</h3><div id="extra-result"></div></section>`);const input=panel.querySelector('#extra-file'),drop=panel.querySelector('#extra-drop'),run=panel.querySelector('#extra-run'),info=panel.querySelector('#extra-info'),out=panel.querySelector('#extra-out'),result=panel.querySelector('#extra-result');let files=[];const select=list=>{files=[...list].filter(f=>f.type==='application/pdf'||f.name.toLowerCase().endsWith('.pdf'));if(!files.length){toast('Select a PDF file.','error');return;}if(!merge&&files.length>1)files=files.slice(0,1);info.textContent=files.map(f=>`${f.name} (${formatBytes(f.size)})`).join(' · ');run.disabled=false;};drop.onclick=()=>input.click();drop.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();input.click();}};input.onchange=e=>select(e.target.files);drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover');};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');select(e.dataTransfer.files);};run.onclick=async()=>{try{run.disabled=true;const {PDFDocument}=await loadPdfLib();const docs=await Promise.all(files.map(async file=>PDFDocument.load(await file.arrayBuffer())));if(id==='pdf-page-counter'||id==='pdf-metadata-viewer'){const doc=docs[0],meta=`Pages: ${doc.getPageCount()}\nTitle: ${doc.getTitle()||'(not set)'}\nAuthor: ${doc.getAuthor()||'(not set)'}\nSubject: ${doc.getSubject()||'(not set)'}`;result.textContent=meta;}else{const target=await PDFDocument.create();if(merge){for(const doc of docs){const pages=await target.copyPages(doc,doc.getPageIndices());pages.forEach(page=>target.addPage(page));}}else{const count=docs[0].getPageCount(),selected=new Set();for(const part of panel.querySelector('#extra-pages').value.split(',')){const range=part.trim().match(/^(\d+)(?:-(\d+))?$/);if(!range)throw Error('Use page numbers such as 1,3-5.');const start=Number(range[1]),end=Number(range[2]||range[1]);if(start<1||end<start||end>count)throw Error(`Page range must be between 1 and ${count}.`);for(let p=start;p<=end;p++)selected.add(p-1);}const pages=await target.copyPages(docs[0],[...selected].sort((a,b)=>a-b));pages.forEach(page=>target.addPage(page));}const bytes=await target.save(),blob=new Blob([bytes],{type:'application/pdf'}),a=document.createElement('button');a.className='btn btn-primary';a.textContent='Download PDF';a.onclick=()=>downloadBlob(blob,merge?'merged.pdf':'extracted-pages.pdf');result.replaceChildren(document.createTextNode(`Created a PDF with ${target.getPageCount()} page(s). `),a);}out.classList.add('visible');}catch(error){result.textContent=error.message||'PDF processing failed.';out.classList.add('visible');}finally{run.disabled=false;}};}

function renderExtraTool(panel){const id=state.currentTool.id;if(['text','text-tools'].includes(TOOLS.find(t=>t.id===id).category))return extraTextTool(panel,id);if(['json-minifier','json-to-csv','csv-to-json','html-encoder','html-decoder','jwt-decoder','timestamp-converter','regex-tester','css-minifier','xml-validator'].includes(id))return extraDeveloperTool(panel,id);if(TOOLS.find(t=>t.id===id).category==='networking')return extraNetworkingTool(panel,id);if(TOOLS.find(t=>t.id===id).category==='calculator')return extraCalculator(panel,id);if(TOOLS.find(t=>t.id===id).category==='datetime')return extraDateTool(panel,id);if(TOOLS.find(t=>t.id===id).category==='student')return extraStudentTool(panel,id);if(TOOLS.find(t=>t.id===id).category==='security'){if(id==='password-strength-checker'){extraTextTool(panel,'character-counter');panel.querySelector('#extra-input').type='password';panel.querySelector('#extra-run').onclick=()=>{const p=panel.querySelector('#extra-input').value;const score=[p.length>=12,/[a-z]/.test(p),/[A-Z]/.test(p),/\d/.test(p),/[^\da-z]/i.test(p)].filter(Boolean).length;panel.querySelector('#extra-result').textContent=`Length: ${p.length}\nChecklist score: ${score}/5\n${score>=4?'Good diversity; prefer a long, unique passphrase.':'Consider a longer, unique password with varied character types.'}\nThis heuristic is not a security audit.`;panel.querySelector('#extra-out').classList.add('visible');};}else{extraShell(panel,'Random String Generator','<div class="grid-2"><div class="form-group"><label for="extra-length">Length (1-256)</label><input id="extra-length" type="number" min="1" max="256" value="32"></div><div class="form-group"><label for="extra-chars">Character set</label><select id="extra-chars"><option value="abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789">Alphanumeric</option><option value="0123456789abcdef">Hexadecimal</option><option value="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789!@#$%&*_-+">Alphanumeric + symbols</option></select></div></div><button class="btn btn-primary" id="extra-run">Generate</button><section class="output-area" id="extra-out"><h3>Random string</h3><pre class="output-content" id="extra-result"></pre><button class="btn btn-secondary" id="extra-copy">Copy</button></section>');panel.querySelector('#extra-run').onclick=()=>{const length=Math.max(1,Math.min(256,Number(panel.querySelector('#extra-length').value)||1)),chars=panel.querySelector('#extra-chars').value;const values=new Uint32Array(length);crypto.getRandomValues(values);const output=[...values].map(n=>chars[n%chars.length]).join('');panel.querySelector('#extra-result').textContent=output;panel.querySelector('#extra-out').classList.add('visible');};panel.querySelector('#extra-copy').onclick=()=>copyText(panel.querySelector('#extra-result').textContent);}}else if(TOOLS.find(t=>t.id===id).category==='image')return extraImageTool(panel,id);else if(TOOLS.find(t=>t.id===id).category==='pdf')return extraPdfTool(panel,id);}

/* Bring legacy unit conversions into dedicated, preselected routes. */
['length','weight','temperature','speed','area','volume','data'].forEach(kind=>{const id=kind==='data'?'data-storage-converter':`${kind}-converter`;if(TOOLS.some(t=>t.id===id))return;const names={length:'Length Converter',weight:'Weight Converter',temperature:'Temperature Converter',speed:'Speed Converter',area:'Area Converter',volume:'Volume Converter',data:'Data Storage Converter'};EXTRA_TOOL_DEFS.push({id,name:names[kind],category:'calculator',icon:'↔',description:`Convert common ${kind==='data'?'data storage':kind} units accurately.`,render:panel=>{renderUnitConverter(panel);const select=panel.querySelector('#uc-category');select.value=kind;select.dispatchEvent(new Event('change'));}});});

['image-compressor','image-resizer','image-converter','image-to-base64','images-to-pdf','image-flipper','image-rotator','grayscale-image','image-color-picker','image-metadata-viewer','merge-pdf','split-pdf','pdf-page-counter','json-formatter','base64-encoder','url-encoder','hash-generator','uuid-generator','color-picker','qr-generator','qr-scanner','stopwatch','random-number','percentage-calc','password-generator'].forEach(id=>{const tool=TOOLS.find(t=>t.id===id);if(!tool)return;const original=tool.render;tool.render=panel=>{original(panel);};});
